+				counts[inv.agent_id] = (counts[inv.agent_id] || 0) + 1;
+			}
+		}
+		return counts;
+	});
+
+	// Reload on project change
+	$effect(() => {
+		const version = getProjectVersion();
+		if (version > 0) {
+			loadData();
+		}
+	});
+
+	async function loadData() {
+		loading = true;
