	 * AC: @web-dashboard ac-32
	 */
	subscribe(topics: string[]): void {
		// Track subscriptions
		for (const topic of topics) {
			if (!this.subscriptions.has(topic)) {
				this.subscriptions.set(topic, {
					topic,
					subscribed_at: new Date()
