		if (this.isConnected()) {
			this.sendCommand({
				action: 'subscribe',
				request_id: crypto.randomUUID(),
				payload: { topics }
			});
		}
	}

	/**
	 * Unsubscribe from topics
	 */
	unsubscribe(topics: string[]): void {
		for (const topic of topics) {
			this.subscriptions.delete(topic);
		}

		if (this.isConnected()) {
			this.sendCommand({
				action: 'unsubscribe',
				request_id: crypto.randomUUID(),
				payload: { topics }
			});
		}
	}

	/**
